from form_function_common import *

def add_b31(b):
    start=len(b.questions);code='B3.1'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    items=[('size','Why exchange surfaces are needed','Why does a large multicellular animal usually require specialized gas-exchange surfaces?','Its external surface area is small relative to its volume, and many cells are far from that surface.',['Large organisms cannot carry out diffusion anywhere.','Oxygen molecules become larger inside a large animal.','All internal cells are directly exposed to air.'],'A low surface-area-to-volume ratio and long diffusion distances make exchange across the outer body surface insufficient for many cells.'),('surface','Features that promote diffusion','Which combination best supports rapid gas exchange?','A large, thin, moist and permeable surface with maintained gradients.',['A small, thick, dry impermeable surface.','A surface with no concentration difference across it.','A barrier that prevents all contact with fluid.'],'Large area and a short diffusion path increase exchange; moisture permits gases to dissolve and maintained gradients support net diffusion.'),('inspiration','Starting a quiet inspiration','What occurs during a normal quiet inspiration in a mammal?','The diaphragm contracts, thoracic volume increases and air enters as lung pressure falls below atmospheric pressure.',['The diaphragm relaxes and pushes air into the lungs.','Thoracic volume decreases while air enters.','Air is actively pumped across each alveolar membrane by ATP-driven transporters.'],'Contraction enlarges the thorax; the resulting pressure decrease draws air through the airways.'),('leaf-path','A route through a leaf','After carbon dioxide enters a typical dicot leaf through a stoma, which route helps it reach photosynthetic cells?','Intercellular air spaces in the mesophyll.',['Only the interior of dead xylem vessels.','A continuous impermeable cuticle blocking the mesophyll.','The central vacuoles of every cell without crossing membranes.'],'Connected air spaces provide a diffusion route from stomata towards moist mesophyll cell surfaces.')]
    for key,title,stem,ans,wrong,why in items:b.add(code,'B31-'+key,title,stem,options=[ans]+wrong,reason=why)
    q('B31-alveolar-illustration','The air-to-blood barrier','The original illustration shows an alveolar air space above a blood capillary. A labels the thin air-facing cell layer, B labels the neighbouring capillary cell layer, and C labels a cell inside the capillary lumen.',P('Identify A, B and C.',A('A: alveolar epithelium.'),A('B: capillary endothelium.'),A('C: an erythrocyte, or red blood cell.')),P('State the net direction of oxygen and carbon dioxide diffusion during normal pulmonary gas exchange.',A('Oxygen moves from alveolar air into blood; carbon dioxide moves from blood into alveolar air.')),P('Explain how the structure shown supports rapid exchange.',R('The thin, closely associated cell layers create a short diffusion path.'),R('The alveolar-capillary interface provides a large area for exchange across many alveoli.')))
    q('B31-gradient-maintenance','Fresh air and flowing blood','An alveolus is ventilated while blood flows through adjacent capillaries.',P('Explain how ventilation and perfusion maintain oxygen diffusion into the blood.',R('Ventilation replenishes oxygen in the alveolar air.'),R('Perfusion brings relatively oxygen-poor blood and carries oxygenated blood away, maintaining a difference across the barrier.')),P('Explain why a moist exchange surface is useful.',A('Gases dissolve in the surface liquid before diffusing across the cell layers.')),P('State one function of surfactant.',A('It lowers surface tension, helping prevent alveolar collapse and reducing the work of expansion.')))
    q('B31-ventilation','Reversing the pressure change','Consider quiet breathing in a resting mammal.',P('Explain how diaphragm and external intercostal activity assist inspiration.',A('The diaphragm contracts and flattens; external intercostals raise the ribs.'),R('Thoracic volume increases, pressure falls below atmospheric pressure, and air enters.')),P('Explain how quiet expiration can occur without active inward compression by the internal intercostals.',A('Inspiratory muscles relax and elastic recoil reduces thoracic and lung volume.'),R('Pressure rises above atmospheric pressure and air flows out.')))
    q('B31-lung-volumes','Separating lung-volume measures','Constructed measurements give a tidal volume of 0.50 L, inspiratory reserve volume of 2.40 L, expiratory reserve volume of 1.20 L and residual volume of 1.30 L. Breathing frequency is 15 breaths per minute.',P('Calculate vital capacity and minute ventilation using the stated tidal volume.',A('Vital capacity = 0.50 + 2.40 + 1.20 = 4.10 L.'),M('Minute ventilation = tidal volume × breaths per minute.'),A('Minute ventilation = 7.5 L per minute.')),P('Explain why residual volume is not part of vital capacity.',A('Residual volume remains after a maximal expiration and cannot be expelled as part of the maximal exchangeable volume.')),P('Explain why minute ventilation is not identical to the volume of fresh air reaching alveoli per minute.',A('Some inhaled air occupies conducting airways and does not reach alveoli during that breath; this is anatomical dead space.')),kind='data-based')
    q('B31-leaf-tissues','Structure of a dicot leaf','The illustration is a simplified transverse section of a dicot leaf. A identifies the densely packed upper mesophyll region, B points into the spaces among lower mesophyll cells and C points to a lower-surface opening.',P('Identify A, B and C.',A('A: palisade mesophyll.'),A('B: intercellular air space in the spongy mesophyll.'),A('C: a stomatal pore.')),P('Explain how the arrangement supports gas exchange while exposing cells to light.',R('The air spaces connect stomata to internal moist cell surfaces, shortening gas diffusion routes.'),R('The upper palisade region receives substantial light and contains many chloroplast-rich photosynthetic cells.')),diagram=leaf_svg())
    counts=[44,48,42,46];area=.20;mean=sum(counts)/len(counts)
    q('B31-stomatal-density','Counting stomata','In a constructed investigation, four non-overlapping fields on one leaf each have area 0.20 mm². The stomatal counts are 44, 48, 42 and 46.',P('Calculate the mean count per field and estimated stomatal density.',A('Mean count = 45 stomata per field.'),M('Divide the mean count by the field area.'),A('Estimated density = 225 stomata per mm².')),P('Explain why four fields from one leaf are not equivalent to four independent plants.',R('Fields share the same leaf and plant history, so they do not represent independent biological replicates of a treatment.')),P('Suggest how the investigation could compare two growing conditions more reliably.',A('Sample multiple independently grown plants in each condition, with comparable leaf age and sampling positions.')),kind='data-based')
    radius=.35;distance=12.0;minutes=10.0;rate=math.pi*radius**2*distance/minutes
    q('B31-potometer','Estimating water uptake','A constructed potometer has a circular capillary of radius 0.35 mm. An air bubble moves 12.0 mm in 10.0 minutes. Assume a leak-free apparatus and use displaced volume '+m(r'V=\pi r^2d')+'.',P('Calculate the mean water-uptake rate.',M('Volume displaced = '+m(r'\pi(0.35)^2(12.0)')+' mm³.'),A(u(rate,r'mm^3\,min^{-1}',2)+'.')),P('Explain why this is an estimate of transpiration rather than a direct measurement of it.',A('The apparatus measures water uptake, which can also supply growth or changes in stored water rather than immediately being lost from leaves.')),P('Predict the usual initial effect of increased air movement around the leaves and explain.',R('Moving air removes humid air near the surface, increasing the water-vapour gradient and often increasing transpiration if stomata remain open.')),kind='data-based')
    q('B31-diffusion-model','Changing diffusion distance','In a constructed model, gas transfer rate is proportional to surface area and inversely proportional to barrier thickness when the concentration difference is fixed. A barrier changes from 0.50 μm to 0.80 μm while its area and concentration difference remain unchanged.',P('Calculate the new rate as a fraction of the original rate.',M('New/original rate = original thickness/new thickness.'),A('The fraction is 0.50/0.80 = 0.625, or 62.5%.')),P('Explain one limitation of applying this result directly to an entire living lung.',A('Total exchange also depends on ventilation, blood flow and the distribution of surface damage or thickness; the simplified model holds these factors constant.')),kind='data-based')
    q('B31-cooperative-binding','Why a dissociation curve is sigmoid','Adult haemoglobin binds oxygen cooperatively.',P('Explain the meaning of cooperative binding.',A('Binding of an initial oxygen molecule changes the haemoglobin conformation.'),R('This increases the affinity of remaining binding sites for oxygen, making subsequent binding easier over part of the range.')),P('Relate this property to the sigmoid oxygen-dissociation curve.',R('Binding is relatively limited at low oxygen partial pressure, then increases steeply as binding promotes further binding before approaching saturation.')),level='ahl')
    q('B31-bohr-data','Comparing two blood pH conditions','The table contains constructed haemoglobin saturation data at the same temperature.'+table(['Oxygen partial pressure / kPa','Saturation at pH 7.4 / %','Saturation at pH 7.2 / %'],[(2,25,12),(4,65,45),(8,90,82),(12,97,94)]),P('Calculate the saturation difference at 4 kPa and state which condition favours oxygen unloading.',A('Saturation is 20 percentage points lower at pH 7.2.'),A('The lower-pH condition favours oxygen unloading at this partial pressure.')),P('Explain how this can assist an actively respiring tissue.',R('Respiring tissue produces more carbon dioxide, which can lower blood pH.'),R('The associated reduction in haemoglobin affinity promotes oxygen release where demand is high; this is the Bohr effect.')),level='ahl',kind='data-based')
    q('B31-fetal-affinity','Oxygen transfer at the placenta','Constructed data at an oxygen partial pressure of 5.0 kPa give 60% saturation for adult haemoglobin and 85% for foetal haemoglobin under matched conditions.',P('Compare the affinities indicated by the data.',A('Foetal haemoglobin has the higher affinity at this partial pressure.'),A('Its saturation is 25 percentage points higher.')),P('Explain how the affinity difference can assist transfer from maternal to foetal blood.',R('Foetal haemoglobin binds oxygen effectively at partial pressures where maternal haemoglobin releases more of it.'),R('Oxygen can diffuse across the placental exchange barrier and bind in foetal blood without the two blood supplies needing to mix.')),level='ahl',kind='data-based')
    capacity=20.0;arterial=.97;rest=.75;active=.35
    q('B31-oxygen-delivery','From saturation to oxygen delivery','For a constructed calculation, fully saturated blood carries 20.0 cm³ oxygen per 100 cm³ blood in haemoglobin. Arterial saturation is 97%; venous saturation is 75% at rest and 35% during activity. Ignore dissolved oxygen and keep haemoglobin concentration unchanged.',P('Calculate the oxygen released per 100 cm³ blood at rest and during activity.',M('Multiply carrying capacity by the fall in fractional saturation.'),A('At rest: '+u(capacity*(arterial-rest),'cm^3')+'; during activity: '+u(capacity*(arterial-active),'cm^3')+'.')),P('Explain why lower venous saturation is consistent with greater oxygen extraction by tissues.',R('More haemoglobin-bound oxygen has been unloaded between the arterial and venous samples.')),P('State one additional measurement needed to calculate total oxygen released to tissues per minute.',A('Blood flow per minute, since a per-volume oxygen amount must be multiplied by the volume of blood supplied per minute.')),level='ahl',kind='data-based')
    assert len(b.questions)-start==16

def add_b32(b):
    start=len(b.questions);code='B3.2'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    items=[('capillary','A short route to tissues','Which feature directly reduces the diffusion distance across a capillary wall?','An endothelium one cell thick.',['A very thick smooth-muscle layer.','A wall made of several layers of impermeable lignin.','A complete absence of contact with tissue fluid.'],'A thin endothelial wall minimizes the distance between blood plasma and the surrounding tissue fluid.'),('artery','Containing high-pressure blood','Which feature is especially important in a typical artery carrying blood from the heart?','A wall containing substantial elastic tissue and smooth muscle.',['An impermeable cellulose wall.','A single unprotected layer with no supporting tissues in any artery.','A lumen permanently closed by valves along its entire length.'],'The wall withstands pressure, stretches during systole and recoils between pulses.'),('vein','Supporting venous return','What is the main role of valves in many limb veins?','They limit backward blood flow.',['They generate oxygen in the blood.','They pump blood by contracting as muscles.','They separate plasma from all blood cells.'],'Valves make flow effectively one-way when surrounding muscles compress veins or pressure changes would otherwise allow backflow.'),('pulse','A travelling pressure change','A pulse is detected at the wrist shortly after ventricular ejection. What does this represent?','A pressure wave causing the arterial wall to expand and recoil.',['One newly ejected red blood cell reaching the wrist at the wave speed.','A contraction of every capillary at the wrist.','Oxygen diffusing along the outside of the artery.'],'The pulse is a propagated pressure and wall-distension wave, not the travel of one particular blood cell.')]
    for key,title,stem,ans,wrong,why in items:b.add(code,'B32-'+key,title,stem,options=[ans]+wrong,reason=why)
    q('B32-artery-section','Relating an artery wall to function','The schematic shows a transverse section of an artery. The wall and lumen are indicated.',P('Explain how a relatively thick wall supports its function.',R('It withstands the high and changing pressure produced by ventricular ejection.'),R('Elastic tissue stretches and recoils, helping maintain flow between heartbeats.')),P('Explain one function of smooth muscle in the wall.',A('Changing smooth-muscle contraction changes lumen diameter and can regulate blood flow or vascular resistance.')),diagram=vessel_svg('artery'))
    q('B32-venous-return','Blood moving from a leg towards the heart','A leg vein passes between skeletal muscles and contains valves.',P('Explain how muscle contraction and valves cooperate in venous return.',A('Contracting muscles compress the vein and raise pressure in the compressed region.'),R('Valves limit backflow, directing the displaced blood towards the heart.')),P('Explain why a vein need not have an arterial wall thickness to fulfil this role.',A('Venous pressure is generally lower; return is assisted by external compression and pressure gradients rather than exposure to the same arterial pressure pulses.')))
    q('B32-coronary-data','Interpreting an epidemiological association','A constructed observational study follows two groups with different reported dietary patterns. Over a fixed interval, new coronary-occlusion cases occur in 12 per 1000 people in group P and 5 per 1000 in group Q.',P('Calculate the ratio of the reported occurrence rates.',M('Divide 12 by 5.'),A('The ratio is 2.4:1.')),P('Explain why these results alone do not show that diet caused the difference.',R('The groups may differ in confounding factors such as smoking, age or physical activity.'),R('An observational association does not by itself establish the causal contribution of the dietary pattern.')),P('Explain why obstruction of a coronary artery can damage heart muscle.',A('It reduces the supply of oxygen and respiratory substrates to the heart muscle served by that artery.')),kind='data-based')
    q('B32-xylem','A low-resistance water pathway','Mature xylem vessel elements are joined into tubes and have lignified walls.',P('Explain two structural adaptations for transport.',A('Loss of cellular contents and perforated or absent end walls provide a relatively unobstructed pathway.'),R('Lignified walls provide strength and resist collapse when the water column is under tension.')),P('State the role of pits.',A('They permit lateral movement of water between adjacent vessels or between xylem and surrounding tissues.')))
    q('B32-cohesion-tension','Pulling water through a plant','Water evaporates from moist mesophyll surfaces and leaves a plant through stomata.',P('Explain how this can contribute to upward movement of water in xylem.',R('Evaporation lowers the water content of leaf cells and generates tension in the connected water pathway.'),R('Cohesion between water molecules helps transmit the pull through a continuous water column.')),P('Explain why xylem transport should not be described as a chain of living cells individually pumping each water molecule upward.',A('Mature vessel elements are dead; the principal upward pull in a transpiring plant results from physical tension and cohesion, not ATP-driven pumping at every level.')))
    q('B32-vascular-plans','Two dicot tissue arrangements','The diagrams show two simplified vascular tissue arrangements in transverse section. Red tissue X and blue tissue Y have the same identities in both drawings.',P('Identify which drawing is a typical young dicot stem and which is a typical dicot root.',A('I is the stem, with vascular bundles arranged in a ring.'),A('II is the root, with central star-shaped xylem and phloem between its arms.')),P('Identify tissues X and Y.',A('X is xylem; Y is phloem.')),P('Explain one limitation of using this schematic to identify every root or stem sample.',A('Arrangement can change with species, developmental stage and secondary growth; a simplified typical plan is not universal.')),diagram=vascular_svg())
    q('B32-tissue-fluid','Leaving the capillary without leaving the circulation behind','Water and small solutes move from capillary plasma into the spaces around tissue cells.',P('Explain how capillary pressure can contribute to tissue-fluid formation.',R('Hydrostatic pressure can drive fluid outward across the thin capillary wall.')),P('Explain why tissue fluid is not identical to whole blood.',A('Blood cells are normally retained within intact capillaries.'),A('Most large plasma proteins are also retained, so tissue fluid differs in composition from plasma as well as from whole blood.')),P('State one role of the resulting fluid.',A('It provides an aqueous medium through which oxygen, nutrients and wastes move between capillaries and tissue cells.')),level='ahl')
    q('B32-lymph','Returning fluid from tissues','Some fluid entering tissues does not immediately return directly across blood-capillary walls.',P('Describe how the lymphatic system returns this fluid to the blood.',A('Fluid enters lymphatic capillaries and becomes lymph.'),A('Lymph moves through larger lymphatic vessels and eventually returns to the venous circulation.')),P('Explain the importance of this return.',R('It helps maintain blood fluid volume and limits accumulation of excess fluid in the tissues.')),P('Explain how valves and body movements can assist lymph flow.',A('External compression moves lymph along vessels, while valves limit backward movement.')),level='ahl')
    q('B32-circulation','One or two visits to the heart','Compare a simplified fish circulation with a mammalian circulation.',P('Trace the route from the heart through exchange surfaces and body tissues back to the heart in each.',A('Fish: heart → gills → body tissues → heart.'),A('Mammal: heart → lungs → heart → body tissues → heart.')),P('Explain one advantage of the double circulation.',R('Blood can be repressurized after passing through lung capillaries, supporting high systemic flow while keeping pulmonary pressure lower.')),level='ahl')
    q('B32-heart-path','Following oxygenated blood','A drop of blood has just returned from the lungs to the mammalian heart.',P('Trace its route through the relevant chambers and into the main systemic artery.',A('Pulmonary vein → left atrium → left ventricle → aorta.')),P('Explain why the left ventricular wall is thicker than the right ventricular wall.',R('The left ventricle must generate greater pressure to drive blood through the systemic circuit.')),P('Explain why heart muscle requires its own coronary blood supply.',A('The thick muscle cannot obtain adequate oxygen and nutrients simply by diffusion from blood within the chambers; coronary vessels supply the tissue directly.')),level='ahl')
    q('B32-pressure-valves','Inferring valve states from pressure','The table gives constructed instantaneous pressures in a left atrium, left ventricle and aorta. Ignore inertia and assume normal pressure-operated valves.'+table(['Time','Atrial / mmHg','Ventricular / mmHg','Aortic / mmHg'],[('P',8,20,80),('Q',8,110,90),('R',8,90,100),('S',8,5,80)]),P('At which listed time is the aortic valve driven open? Explain.',A('Q.'),R('Ventricular pressure exceeds aortic pressure, favouring flow from ventricle to aorta.')),P('At which listed time is the left atrioventricular valve driven open? Explain.',A('S.'),R('Atrial pressure exceeds ventricular pressure, favouring filling of the ventricle.')),P('Explain why valves need not actively contract to open and close.',A('The pressure differences move the valve flaps; their structure limits flow in the wrong direction.')),level='ahl',kind='data-based')
    q('B32-positive-pressure','Pressure and living support in plant transport','Positive pressure can occur in root xylem under some conditions. Phloem transport, in contrast with mature xylem vessels, also relies on living sieve-tube elements and companion cells.',P('Explain how root pressure can arise.',A('Active accumulation of mineral ions in root xylem promotes osmotic water entry.'),R('The entering water can generate a positive hydrostatic pressure, especially when transpiration is low.')),P('Explain two phloem structural adaptations.',A('Sieve-tube elements have reduced contents and perforated sieve plates, allowing sap movement with relatively low resistance.'),A('Companion cells retain metabolic machinery and are connected to sieve elements, supporting functions including solute loading and maintenance.')),P('Explain why root pressure is not a sufficient general explanation for water reaching the tops of tall trees.',A('It is not consistently large enough and may be absent during strong transpiration; cohesion-tension provides the main upward mechanism in those conditions.')),level='ahl')
    assert len(b.questions)-start==16

def add_b33(b):
    start=len(b.questions);code='B3.3'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),level='ahl',**kw)
    items=[('sessile','Movement without locomotion','Which statement correctly distinguishes movement from locomotion?','A sessile organism can move parts of its body without changing its overall location.',['Every movement must move the whole organism to another place.','Plants and attached animals cannot show any movement.','Locomotion occurs only inside single cells.'],'Movement is broader than whole-organism locomotion; a sessile organism may change the position of particular structures.'),('sliding','What becomes shorter?','During contraction of a sarcomere, which change occurs?','The distance between its Z discs decreases while actin and myosin filament lengths remain approximately constant.',['Every actin filament is hydrolysed to half its length.','The thick filaments disappear entirely.','The distance between Z discs increases.'],'Contraction is produced by filament sliding and increased overlap, not by shortening individual filaments.'),('titin','An elastic sarcomere component','Which role is associated with titin?','Elastic support and recoil, helping maintain thick-filament position within the sarcomere.',['Pumping calcium out of every blood cell.','Forming the external bone surface.','Replacing ATP as the energy source of cross-bridge cycling.'],'Titin is an elastic protein that contributes to structural organization and recoil of muscle.'),('unit','One neuron and its muscle fibres','What is a motor unit?','A motor neuron and all the muscle fibres it innervates.',['Every neuron in a whole organism.','One actin monomer and one ATP molecule.','A joint plus every bone in the skeleton.'],'Fibres within one motor unit receive input from the same motor neuron.')]
    for key,title,stem,ans,wrong,why in items:b.add(code,'B33-'+key,title,stem,options=[ans]+wrong,reason=why,level='ahl')
    q('B33-sarcomere-map','Reading a filament model','The illustration represents part of a striated muscle fibre. Z reference lines define the ends of one sarcomere and M marks its centre. Blue lines represent thin filaments; red lines represent thick filaments.',P('Describe the attachments and arrangement of the two filament types.',A('Thin filaments are attached at the Z discs and extend towards the centre.'),A('Thick filaments are centred around the M line and overlap thin filaments on both sides.')),P('Explain how force on thin filaments produces shortening.',R('Myosin heads form cross-bridges and pull the thin filaments towards the sarcomere centre, bringing the Z discs closer together.')),diagram=sarcomere_svg())
    q('B33-shortening-data','Length changes in a muscle unit','Constructed measurements show a sarcomere shortening from 3.0 μm to 2.4 μm. Its thick-filament length remains 1.6 μm.',P('Calculate the percentage shortening of the sarcomere.',M('Use (3.0 − 2.4)/3.0 × 100.'),A('20% shortening.')),P('Predict the changes in the A band, I band and H zone.',A('The A band, corresponding to thick-filament length, remains approximately constant.'),A('The I band and H zone become narrower as overlap increases.')),P('Explain why a drawing of shorter thick filaments would not represent the sliding-filament model.',R('The model changes filament overlap and sarcomere length while retaining the lengths of the filaments themselves.')),kind='data-based',diagram=sarcomere_svg(True))
    q('B33-atp-cycle','ATP at a cross-bridge','A myosin head is attached to actin during a cross-bridge cycle.',P('Explain the role of ATP binding and ATP hydrolysis at the myosin head.',A('ATP binding permits the myosin head to detach from actin.'),A('ATP hydrolysis provides energy to return the head to a position ready for another cycle.')),P('Explain how repeated cycles can produce a sustained movement.',R('Many heads undergo cycles at different times, maintaining force while individual heads detach and reattach.')))
    q('B33-calcium','Exposing binding sites','In a skeletal muscle fibre, an increase in cytosolic calcium initiates events that allow cross-bridge formation.',P('Explain the role of calcium and the regulatory proteins on the thin filament.',A('Calcium binds to the regulatory complex including troponin.'),R('This shifts tropomyosin away from myosin-binding sites on actin, allowing cross-bridges to form.')),P('Explain why calcium alone is not an energy supply for sustained cycling.',A('ATP is still needed for detachment and re-energizing myosin; calcium regulates access to the binding sites.')))
    q('B33-antagonists','Returning a joint to its starting position','Two muscle groups act on opposite sides of a joint.',P('Explain why antagonistic action is required for movement in both directions.',A('An actively contracting muscle produces a pulling force, not an active pushing force.'),R('One group produces movement in one direction, while the opposing group can produce the reverse movement.')),P('State the roles of tendons and ligaments.',A('Tendons transmit force from muscle to bone; ligaments connect bones and help stabilize joints.')))
    load=18;loadd=.28;muscd=.035;force=load*loadd/muscd
    q('B33-lever','A simplified limb lever','A constructed static limb model has a load of 18 N acting 0.280 m from a joint pivot. The muscle’s perpendicular moment arm is 0.0350 m. Ignore the limb’s own weight. In balance, force × moment arm is equal on both sides.',P('Calculate the required muscle force.',M('Muscle force = 18 × 0.280/0.0350.'),A(u(force,'N',2)+'.')),P('Explain why a short muscle moment arm can still be useful despite requiring a large force.',R('A small shortening of the muscle can produce a relatively large displacement and speed of the more distant load.')),P('State one limitation of this model.',A('Accept changing moment arms with joint angle, the limb’s own mass, multiple muscles or dynamic acceleration.')),kind='data-based')
    q('B33-hip','A stable joint with broad movement','The hip is a ball-and-socket joint linking the femur to the pelvis.',P('Relate the ball-and-socket arrangement to range of movement.',A('The rounded femoral head fits into a pelvic socket, allowing movement about more than one axis.')),P('Explain the roles of cartilage, synovial fluid and ligaments.',A('Articular cartilage and synovial fluid reduce friction and help distribute forces at the joint surfaces.'),A('Ligaments help hold the bones in a stable relationship while limiting excessive movement.')),P('Explain why a larger possible range is not always the only desirable joint property.',R('Greater range can trade off against stability and resistance to displacement under load.')))
    values=[110,107,112];mean=sum(values)/3
    q('B33-range-data','Measuring a range of movement','In a constructed investigation, a goniometer measures the difference between two comfortable joint positions on three repeated trials: 110°, 107° and 112°. No clinical conclusion is requested.',P('Calculate the mean measured range.',M('Add the three values and divide by three.'),A(u(mean,'degree')+'; approximately 110°.')),P('Suggest two practices that improve comparability of repeated measurements.',A('Use the same anatomical landmarks and instrument alignment.'),A('Standardize the starting posture and measurement method; do not force the joint beyond the defined comfortable endpoint.')),P('Explain why these repeated trials do not describe variation among people.',R('They are repeated measurements of one participant; independent participants are needed to estimate between-person variation.')),kind='data-based')
    q('B33-intercostals','Antagonists during forced breathing','Compare inspiration with active forced expiration in a mammal.',P('State how the external and internal intercostal groups contribute to opposite rib movements.',A('External intercostals assist elevation of the ribs during inspiration.'),A('Internal intercostals assist depression of the ribs during active forced expiration.')),P('Explain how these movements affect thoracic volume and airflow.',R('Raising the ribs increases thoracic volume and helps lower pressure for inward flow; lowering them reduces volume and helps raise pressure for outward flow.')),P('Explain why this description should not imply that all quiet expirations require active internal intercostal contraction.',A('Quiet expiration can be largely passive through relaxation and elastic recoil.')))
    q('B33-locomotion-purpose','Benefits and costs of locomotion','A mobile animal can move between feeding, breeding and shelter sites.',P('State two possible biological benefits of locomotion.',A('Accessing food or water supplies resources needed for survival; accept a different valid benefit for this point.'),A('Reaching mates can increase reproductive opportunities; alternatively credit escaping predators, locating shelter or dispersal, provided it is distinct from the first benefit.')),P('Explain why movement is not always advantageous at every moment.',R('Locomotion costs energy and may expose the animal to danger; benefits depend on environmental conditions and the activity undertaken.')))
    q('B33-marine-mammal','Moving through water','A marine mammal has a streamlined body, flippers, a muscular tail with horizontal flukes and a layer of blubber.',P('Explain the functions of (i) streamlining, (ii) the flippers and tail, and (iii) blubber.',A('Streamlining reduces resistance as water passes around the body.'),A('Flippers assist steering and stability; tail flukes driven by muscular movement provide propulsion.'),A('Blubber reduces heat loss and also provides an energy store.')),P('Explain why a swimming adaptation should be evaluated as part of an integrated body design.',R('Propulsion, drag, steering, breathing and temperature control impose interacting demands; changing one feature may affect several functions.')))
    q('B33-recruitment-data','Graded whole-muscle force','A constructed model holds stimulation frequency constant and treats each recruited motor unit as contributing the same force. Recruiting 2, 4 and 6 units gives total forces of 6, 12 and 18 N, respectively.',P('Determine the model force per motor unit and predict the force from 3 units.',A('Each unit contributes 3 N.'),A('Three units give 9 N.')),P('Explain how recruitment allows graded force despite individual muscle-fibre responses being all-or-none under the stated stimulation conditions.',R('Changing the number of active units changes the number of fibres contributing force.')),P('Explain why a muscle with smaller motor units can provide finer control.',A('Recruiting one additional small unit changes the total force by a smaller increment.')),kind='data-based')
    assert len(b.questions)-start==16
